// Inventory target machine via Tailscale SSH
const target = $json.target || 'legion-pc';
const authKey = $env.TAILSCALE_AUTH_KEY;

return [{ json: {
  target,
  authKey,
  commands: [
    'uname -a',
    'docker --version',
    'n8n --version 2>/dev/null || echo n8n not installed',
    'openclaw --version 2>/dev/null || echo openclaw not installed',
    'tailscale status --json'
  ]
}}];

// Run Ansible playbook for remediation
const inventory = $json[0];
const needsDocker = !inventory.stdout?.includes('docker');
const needsN8n = !inventory.stdout?.includes('n8n');
const needsOpenclaw = !inventory.stdout?.includes('openclaw');

return [{ json: {
  target: $json.target,
  playbook: 'playbooks/legion-fix.yml',
  extraVars: {
    install_docker: needsDocker,
    install_n8n: needsN8n,
    install_openclaw: needsOpenclaw,
    tailscale_auth_key: $json.authKey
  }
}}];

// Execute remediation via SSH
const { execSync } = require('child_process');
const target = $json.target;
const playbook = $json.playbook;
const extraVars = JSON.stringify($json.extraVars).replace(/

');

try {
  execSync(`ansible-playbook -i ${target}, ${playbook} --extra-vars '${extraVars}'`, { stdio: 'pipe' });
  return [{ json: { status: 'success', target } }];
} catch (e) {
  return [{ json: { status: 'error', target, error: e.message } }];
}

// Verify Legion node is online
const target = $json.target;
const { execSync } = require('child_process');
try {
  const ping = execSync(`tailscale ping ${target}`, { encoding: 'utf8' });
  const devices = execSync('openclaw devices list', { encoding: 'utf8' });
  return [{ json: { status: 'verified', ping, devices } }];
} catch (e) {
  return [{ json: { status: 'failed', error: e.message } }];
}
